// Общие шаги для картинок в карточках объявлений (#0a2499): главная и /search.
// Прод — только просмотр: все не-GET запросы окна блокируются (кроме чтения через RPC, например is_admin).
// Объявления не хардкодятся: проверяются все показанные карточки.
// Окно медиа карточки не имеет роли/подписи — ищется по классу соотношения сторон `.aspect-[4/3]`
// (это и есть проверяемое свойство «окно 4:3»), значки — по title/aria-label.
import { expect, Page } from '@playwright/test';

export const MEDIA = '.aspect-\\[4\\/3\\]';
export const STONE_50 = 'rgb(250, 250, 249)';
const LOAD = { timeout: 20_000 };
const SAFE_METHODS = ['GET', 'HEAD', 'OPTIONS'];
// RPC с такими именами — запись; остальные RPC (is_admin, get_…) — чтение, пропускаем.
const WRITE_RPC = /increment|track|insert|update|delete|create|upsert|add_|remove|set_|toggle|log/i;

export type Img = { fit: string; src: string; visible: boolean; nat: [number, number]; box: [number, number, number, number] };
export type Card = {
  idx: number;
  section: string;
  box: [number, number, number, number]; // x, y, w, h окна медиа
  cardW: number;
  bg: string;
  imgs: Img[];
  video: { fit: string; w: number; h: number } | null;
};

/** Блок записи и автозакрытие попапов (cookie — «חיוניים בלבד», PWA — «אולי מאוחר יותר»). До первого перехода. */
export async function prepare(page: Page) {
  await page.context().route('**/*', (route) => {
    const r = route.request();
    if (SAFE_METHODS.includes(r.method())) return route.fallback();
    const rpc = r.url().split('?')[0].match(/\/rest\/v1\/rpc\/([^/]+)$/);
    if (rpc && !WRITE_RPC.test(rpc[1])) return route.fallback();
    return route.abort('blockedbyclient');
  });
  await page.addLocatorHandler(page.getByText('חיוניים בלבד', { exact: true }), (l) => l.click());
  await page.addLocatorHandler(page.getByRole('button', { name: 'אולי מאוחר יותר' }), (l) => l.click());
}

/** Открыть страницу с карточками и дождаться первой картинки/видео в окне медиа. */
export async function openCards(page: Page, path: '/' | '/search') {
  await page.goto(path);
  await expect(page.locator(MEDIA).first(), `карточки на ${path}`).toBeVisible(LOAD);
  await expect(page.locator(`${MEDIA} img, ${MEDIA} video`).first()).toBeAttached(LOAD);
}

/** Прокрутить первые n окон медиа в видимость и дождаться загрузки их видимых картинок (lazy). */
export async function loadFirst(page: Page, n: number) {
  const media = page.locator(MEDIA);
  const count = Math.min(n, await media.count());
  for (let i = 0; i < count; i++) {
    const m = media.nth(i);
    if (!(await m.isVisible())) continue; // скрытый слайд карусели
    await m.scrollIntoViewIfNeeded();
    const img = m.locator('img:not(.opacity-0)').first();
    if (await img.count())
      await expect
        .poll(() => img.evaluate((el: HTMLImageElement) => el.complete && el.naturalWidth > 0), { ...LOAD, message: `картинка карточки ${i} загрузилась` })
        .toBe(true);
  }
  await page.evaluate(() => window.scrollTo(0, 0));
}

/** Снимок всех видимых окон медиа: размеры, фон, картинки, видео. */
export async function readCards(page: Page): Promise<Card[]> {
  return page.locator(MEDIA).evaluateAll((els) =>
    els
      .map((m, idx) => {
        const r = m.getBoundingClientRect();
        const card = (m.closest('.rounded-xl') as HTMLElement) || m.parentElement!;
        const box = (e: Element): [number, number, number, number] => {
          const b = e.getBoundingClientRect();
          return [b.left, b.top, b.width, b.height];
        };
        const v = m.querySelector('video');
        return {
          idx,
          section: (m.closest('section')?.querySelector('h2')?.textContent || '').trim(),
          box: box(m),
          cardW: card.getBoundingClientRect().width,
          bg: getComputedStyle(m).backgroundColor,
          imgs: [...m.querySelectorAll('img')].map((i) => ({
            fit: getComputedStyle(i).objectFit,
            src: i.getAttribute('src') || '',
            visible: !i.classList.contains('opacity-0'),
            nat: [i.naturalWidth, i.naturalHeight] as [number, number],
            box: box(i),
          })),
          video: v ? { fit: getComputedStyle(v).objectFit, w: v.getBoundingClientRect().width, h: v.getBoundingClientRect().height } : null,
          _w: r.width,
        };
      })
      .filter((c) => c._w > 0)
      .map(({ _w, ...c }) => c),
  );
}

export const visibleImg = (c: Card) => c.imgs.find((i) => i.visible) || c.imgs[0];
export const originalOf = (src: string) => src.replace(/\.card2\.webp(\?.*)?$/, '');

/** Натуральный размер оригиналов (браузер учитывает EXIF-поворот). null — не загрузился. */
export async function naturalSizes(page: Page, urls: string[]): Promise<([number, number] | null)[]> {
  return page.evaluate(
    (list) =>
      Promise.all(
        list.map(
          (u) =>
            new Promise<[number, number] | null>((res) => {
              const i = new Image();
              i.onload = () => res([i.naturalWidth, i.naturalHeight]);
              i.onerror = () => res(null);
              i.src = u;
            }),
        ),
      ),
    urls,
  );
}

/** Картинка карточки не обрезается: нет cover, видимая — contain на всё окно, файл .card2.webp. */
export function expectUncropped(cards: Card[], where: string) {
  const withImg = cards.filter((c) => c.imgs.length && !c.video);
  expect(withImg.length, `${where}: есть карточки с картинкой`).toBeGreaterThan(0);
  for (const c of withImg) {
    const covers = c.imgs.filter((i) => i.fit === 'cover');
    expect(covers.map((i) => i.src), `${where}, карточка ${c.idx}: нет object-fit cover`).toEqual([]);
    const img = visibleImg(c);
    expect(img.fit, `${where}, карточка ${c.idx}: object-fit`).toBe('contain');
    // Картинка растянута на всё окно (inset-0) → при contain нарисована целиком внутри окна.
    expect(Math.abs(img.box[2] - c.box[2]), `${where}, карточка ${c.idx}: ширина img = окну`).toBeLessThanOrEqual(1);
    expect(Math.abs(img.box[3] - c.box[3]), `${where}, карточка ${c.idx}: высота img = окну`).toBeLessThanOrEqual(1);
    expect(img.src, `${where}, карточка ${c.idx}: файл без обрезки .card2.webp`).toMatch(/\.card2\.webp(\?|$)/);
  }
}

/** Окно медиа 4:3 во всю ширину карточки. */
export function expectWindow43(cards: Card[], where: string) {
  for (const c of cards) {
    const ratio = c.box[2] / c.box[3];
    expect(Math.abs(ratio - 4 / 3) / (4 / 3), `${where}, карточка ${c.idx}: окно 4:3 (${c.box[2].toFixed(0)}×${c.box[3].toFixed(0)})`).toBeLessThanOrEqual(0.015);
    expect(c.box[2], `${where}, карточка ${c.idx}: окно во всю ширину карточки`).toBeGreaterThanOrEqual(c.cardW - 4);
  }
}

/** Нейтральный светлый фон (серый без оттенка, не чёрный). */
export function isNeutralLight(rgb: string) {
  const m = rgb.match(/\d+/g)?.map(Number) || [];
  if (m.length < 3 || (m.length === 4 && m[3] === 0)) return false;
  const [r, g, b] = m;
  return Math.min(r, g, b) >= 235 && Math.max(r, g, b) - Math.min(r, g, b) <= 6;
}

/** Поля нарисованной картинки (contain) по осям X и Y, px. */
export function padding(c: Card, img: Img) {
  const [W, H] = [c.box[2], c.box[3]];
  const s = Math.min(W / img.nat[0], H / img.nat[1]);
  return { x: (W - img.nat[0] * s) / 2, y: (H - img.nat[1] * s) / 2 };
}
